func NewWEB3Client(cfg *WEB3ClientConfig, clientLogger *logrus.Entry) WEB3Client {
	if cfg == nil || cfg.BaseURL == "" {
		return nil
	}

	tracingBefore, tracingAfter := middleware.TracingMiddleware(WEB3ClientFeature)

	client := req.C().
		SetBaseURL(cfg.BaseURL).
		OnBeforeRequest(tracingBefore).
		OnAfterResponse(tracingAfter)

	return &web3Client{
		client:       client,
		config:       cfg,
		clientLogger: clientLogger,
	}
}

