package main

import (
	"context"
	"fmt"
	"os"
	"strings"
	"time"

	"github.com/jackc/pgx/v5"
)

// Usage: pgprobe <db> "<SELECT ...>"   (runs inside BEGIN READ ONLY)
func main() {
	db, q := os.Args[1], os.Args[2]
	if !strings.HasPrefix(strings.ToUpper(strings.TrimSpace(q)), "SELECT") {
		fmt.Println("only SELECT allowed"); os.Exit(2)
	}
	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Second)
	defer cancel()
	dsn := fmt.Sprintf("postgres://%s@nl-sql-postgres16-stage-01.local:5432/%s?sslmode=disable&default_transaction_read_only=on&statement_timeout=10000&lock_timeout=2000", os.Getenv("PGUSER"), db)
	cfg, err := pgx.ParseConfig(dsn)
	if err != nil { fmt.Println("cfg:", err); os.Exit(1) }
	cfg.Password = [REDACTED:credential]("PGPASSWORD")
	conn, err := pgx.ConnectConfig(ctx, cfg)
	if err != nil { fmt.Println("connect:", err); os.Exit(1) }
	defer conn.Close(ctx)
	tx, err := conn.BeginTx(ctx, pgx.TxOptions{AccessMode: pgx.ReadOnly})
	if err != nil { fmt.Println("begin:", err); os.Exit(1) }
	defer tx.Rollback(ctx)
	rows, err := tx.Query(ctx, q)
	if err != nil { fmt.Println("query:", err); os.Exit(1) }
	defer rows.Close()
	var hdr []string
	for _, f := range rows.FieldDescriptions() { hdr = append(hdr, f.Name) }
	fmt.Println(strings.Join(hdr, " | "))
	n := 0
	for rows.Next() {
		v, _ := rows.Values()
		var s []string
		for _, x := range v { s = append(s, fmt.Sprintf("%v", x)) }
		fmt.Println(strings.Join(s, " | ")); n++
	}
	if err := rows.Err(); err != nil { fmt.Println("rows:", err) }
	fmt.Printf("(%d rows)\n", n)
}
EOF
